WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
  AND v.tag IS NOT NULL
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-3701B'}), (v:PlantItem:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND NOT EXISTS {
    MATCH (p)-[:line_to*1..]->(w:PlantItem:Valve)-[:line_to*1..]->(v)
    WHERE w <> v
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

