WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND NOT EXISTS {
    MATCH (p)-[:line_to*1..]->(w:PlantItem:Valve)
    WHERE w <> v AND EXISTS { (w)-[:line_to*1..]->(v) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (d:PlantItem {tag: 'D-4001'}), (v:PlantItem:Valve)
WHERE (v.operating_position = 'NO' OR v.operating_position IS NULL)
  AND EXISTS { (v)-[:line_to*1..]->(d) }
  AND EXISTS {
    MATCH (e:Equipment)
    WHERE EXISTS { (e)-[:line_to*1..]->(v) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-1301A'})-[:line_to*1..]->(v:Valve)
WHERE coalesce(v.operating_position, 'NO') = 'NO'
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (h:PlantItem {tag: 'H-2401'}), (v:Valve)
WHERE EXISTS {
  MATCH (e:Equipment)-[:line_to*1..]->(v)
  WHERE e <> h
}
AND EXISTS {
  MATCH (v)-[:line_to*1..]->(h)
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(t:PlantItem {tag: 'T-901'})
RETURN DISTINCT v.tag AS tag
