MATCH (v:PlantItem:Valve)-[:line_to*1..]->(:PlantItem {tag: 'P-3301A'})
WHERE NOT v:CheckValve
  AND NOT v:GlobeCheckValve
  AND NOT v:SafetyValveOrFitting
  AND NOT EXISTS { (:ActuatingFunction)-[:control]->(v) }
  AND NOT EXISTS { (:ActuatingElectricalFunction)-[:control]->(v) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve), (t:PlantItem:Tank {tag: 'T-3901'})
WHERE EXISTS { (v)-[:line_to*1..]->(t) }
  AND NOT EXISTS { ()-[:control]->(v) }
  AND NOT (v:CheckValve OR v:SwingCheckValve OR v:GlobeCheckValve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag
